{
  "title": "幽谷迷途",
  "scene": "你穿过一片古老的森林，来到了一个隐秘的山谷。山谷中弥漫着淡淡的雾气，四周长满了奇异的植物，其中一些你从未见过。在山谷的中央，有一块巨大的磐石，上面刻着古老的符文，似乎在诉说着某种力量。山谷的北侧有一座小木屋，门口坐着一位须发皆白的老人，正闭目养神。南侧则有一条清澈的小溪，溪边有一只看似温顺的青鸾鸟正在嬉戏。据传说，这里藏有一件上古神器，但具体位置不详。",
  "goal": "找到并获取上古神器",
  "clue": "巨大的磐石上的古老符文暗示了神器的位置。",
  "choices": [
    {
      "id": "A",
      "text": "上前与老人交谈",
      "outcome": "老人缓缓睁开眼睛，告诉你这件神器被封印在磐石之下，但需要解开符文的谜题才能取出。你决定返回寻找线索，再尝试。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "靠近青鸾鸟观察",
      "outcome": "青鸾鸟见你靠近，突然变得警觉，发出一声尖锐的鸣叫，山谷中顿时出现一阵强风，将你吹回了原地。你意识到，青鸾鸟是守护神器的灵兽。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "仔细研究磐石上的符文",
      "outcome": "经过仔细研究，你发现符文中隐藏着一个机关。你按照符文的指示，轻轻按下了岩石上的一个凹槽，岩石缓缓裂开，露出了一个光芒四射的宝箱。你成功找到了上古神器。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
